import java.util.ArrayList;
import java.util.List;

public class Demo {
    public static void main(String[] args) {
        String[] lines = {"Linh,85", "An,abc", "Mai, 50", "Binh,120", "Tuan"};
        List<Student> students = new ArrayList<>();
        int rejected = 0;
        for (String line : lines) {
            try {
                students.add(Student.parse(line));
            } catch (IllegalArgumentException e) {
                rejected++;
                System.out.println("Rejected \"" + line + "\": " + e.getMessage());
            }
        }
        String passed = "";
        for (Student s : students) {
            if (s.passes()) passed += s.getName() + " ";
        }
        System.out.println("read=" + lines.length + ", stored=" + students.size() + ", rejected=" + rejected);
        System.out.println("passed: " + passed.trim());
    }
}

class Student {
    private final String name;
    private final int mark;

    Student(String name, int mark) {
        if (mark < 0 || mark > 100) {
            throw new IllegalArgumentException("mark out of range: " + mark);
        }
        this.name = name;
        this.mark = mark;
    }

    static Student parse(String line) {
        String[] parts = line.split(",");
        if (parts.length != 2) {
            throw new IllegalArgumentException("expected 2 fields, got " + parts.length);
        }
        return new Student(parts[0], Integer.parseInt(parts[1].trim()));
    }

    String getName() { return name; }

    boolean passes() { return mark >= 50; }
}

def parse(line):
    fields = line.split(",")
    if len(fields) != 2:
        raise ValueError(f"expected 2 fields, got {len(fields)}")
    name, text = fields
    mark = int(text)
    if not 0 <= mark <= 100:
        raise ValueError(f"mark out of range: {mark}")
    return name.strip(), mark

lines = ["Linh,85", "An,abc", "Mai, 50", "Binh,120", "Tuan", ""]
records, rejected = [], []
for number, line in enumerate(lines, 1):
    try:
        records.append(parse(line))
    except ValueError as error:
        rejected.append((number, str(error)))

print("read:", len(lines), "stored:", len(records))
for number, reason in rejected:
    print(f"  line {number}: {reason}")
passed = [name for name, mark in records if mark >= 50]
print("passed:", ", ".join(passed))

